"""Publish actual native views and scoped test results for the first Shadow Game."""
import hashlib
import html
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[3]
native = json.loads((HERE / "checks.json").read_text(encoding="utf-8"))
menu_path = HERE / "menu-checks.json"
menu = json.loads(menu_path.read_text(encoding="utf-8")) if menu_path.exists() else {"checks":[], "passed":False}
paths = list((ROOT / "commons/shadow_game").glob("*.gd")) + [ROOT / "commons/shadow_game/shadow_game.tscn", ROOT / "commons/shadow_game/README.md", ROOT / "tools/test_shadow_game.py"]
paths += list((ROOT / 'commons/museum_runner/forms').glob('*'))
paths += [ROOT / 'tools/test_museum_runner_package.py', ROOT / 'tools/probes/museum_runner_package_probe.gd']
paths += [ROOT / p for p in ["commons/scenes/main_menu/MainMenu3D.gd", "commons/scenes/main_menu/MainMenu3D.tscn", "doc/book/iterations/2026-10-06-starter-one-course/lessons/Point_Lines/point_body.gd", "doc/book/iterations/2026-10-06-starter-one-course/lessons/Point_Lines/line_skin.gd", "doc/book/iterations/2026-10-16-scale-carried-frame/complete/box_body.gd"]]
manifest = {"status":"first playable episode", "native":native, "menu":menu, "sources":{str(p.relative_to(ROOT)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}, "limits":["Synthetic native input; physical headset not tested.", "Biome is supplied environment; the learner has not generated its ecology.", "This scene records its own trace, separate from the student archive."]}
manifest["native_process"] = json.loads((HERE / "native-process.json").read_text(encoding="utf-8"))
manifest["menu_process"] = {"exit_code":3221225477,"clean_exit":False,"source":"Recorded menu run; see menu-stdout.log and REPORT.md"}
manifest["limits"].append("Menu assertions pass but staged test still crashes during process shutdown.")
package_path = HERE.parent / '2026-10-17-museum-runner/package-receipt.json'
package = json.loads(package_path.read_text(encoding='utf-8'))
assert package['passed'], 'Do not publish a failed package check as a verified fix.'
manifest['package_verification'] = package
(HERE / "receipt.json").write_text(json.dumps(manifest,indent=2),encoding="utf-8")
native_count = sum(x['passed'] for x in native['checks'])
menu_count = sum(x['passed'] for x in menu['checks'])
links = ''
for p in paths:
    relative = p.relative_to(ROOT).as_posix()
    snapshot = HERE / "sources" / (relative + ".txt")
    snapshot.parent.mkdir(parents=True, exist_ok=True)
    snapshot.write_bytes(p.read_bytes())
    links += f'<li><a href="sources/{html.escape(relative)}.txt">{html.escape(p.name)}</a></li>'
page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shadow Game — Make a crossing</title><style>
:root{color-scheme:dark;--paper:#ede9de;--dim:#a5b9b7;--pink:#e5a9c7}*{box-sizing:border-box}body{margin:0;background:#101a20;color:var(--paper);font:17px/1.65 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:54px 32px 80px}a{color:var(--pink)}nav{display:flex;gap:24px;flex-wrap:wrap;margin:0 0 36px}.kicker{color:var(--pink);text-transform:uppercase;font-size:12px;letter-spacing:.2em}h1{font-size:clamp(48px,7vw,94px);line-height:1.02;font-weight:500;letter-spacing:-.055em;margin:20px 0}h2{font-weight:500;font-size:29px;margin:42px 0 16px}.lead{max-width:720px;font-size:23px;color:#c3d2cc}.hero{width:100%;display:block;border:1px solid #445354}.caption{font-size:14px;color:var(--dim);margin:10px 0 28px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:36px 0}.card{border-top:2px solid #658683;padding:18px 4px}.num{font-size:14px;color:var(--pink)}.card h3{font-size:25px;margin:12px 0}.card p{color:#bbcbc6}.compare{padding-top:12px}.compare input{accent-color:var(--pink);margin:0 6px 18px 16px}.compare input:first-child{margin-left:0}.compare img{width:100%;display:none}#closed:checked~.closed,#open:checked~.open{display:block}aside{padding:24px;border:1px solid #445354;margin:32px 0}code{font-size:14px;overflow-wrap:anywhere}.links{columns:2;padding-left:20px}.links li{margin:5px 0}.small{font-size:14px;color:var(--dim)}@media(max-width:700px){main{padding:28px 18px}.cards{grid-template-columns:1fr}.links{columns:1}.lead{font-size:19px}}@media print{body{background:white;color:black}nav,.compare input,.compare label{display:none}.compare img{display:block}aside{break-inside:avoid}}
</style><main><nav><a href="#play">Play</a><a href="#crossing">Before / after</a><a href="#lineage">What returns</a><a href="#evidence">Evidence &amp; files</a></nav>
<div class="kicker">Endless Museum / first playable episode / 17 October 2026</div><h1>Shadow Game</h1><p class="lead">Make a crossing. Three familiar objects begin to make a world together.</p>
<img class="hero" src="entry.png" alt="A shiny black point on an off-white stand, a cube, a pink stick and an incomplete crossing within the existing biome"><p class="caption">Actual Godot scene. The museum's player, the tutorial's shapes, and the existing biome.</p>
<section id="play"><h2>Open the game menu → Shadow Game</h2><p>Or open <a href="/book-review/commons/shadow_game/shadow_game.tscn">shadow_game.tscn</a> in Godot and run the current scene with F6. An installed Quest build needs a new export.</p><div class="cards"><article class="card"><span class="num">01 / PLACE</span><h3>The cube anchors.</h3><p>Take the cube. Release it inside the pink frame. Its placement powers the hinge.</p></article><article class="card"><span class="num">02 / TURN</span><h3>The stick operates.</h3><p>Hold the stick and press trigger. The beam turns through a quarter-circle and becomes a crossing. Removing the cube pauses it.</p></article><article class="card"><span class="num">03 / CARRY</span><h3>The point remembers.</h3><p>Carry the sphere across and release it on the far plinth. Your movement leaves a trace; the objects remain.</p></article></div><aside><strong>Desktop</strong><br>Arrow keys: walk · Mouse: look · Right click: take / release · Wheel: reach · Left click: held stick action · Escape: cursor.<br><br><strong>VR</strong><br>Use the existing grip pickup and the holding hand's trigger. The same objects and rules are used.<br><br>Release saves the arrangement. A fall returns you to arrival. Recall brings loose objects back. Reset takes two presses.</aside></section>
<section id="crossing"><h2>A line becomes somewhere to walk.</h2><div class="compare"><input type="radio" name="comparison" id="closed" checked><label for="closed">Before</label><input type="radio" name="comparison" id="open"><label for="open">After</label><img class="closed" src="before.png" alt="Bridge turned away from the gap"><img class="open" src="after.png" alt="The same bridge spans the gap and the student's trace remains"></div><p class="caption">Same native scene and viewpoint. The finished crossing remains available for further arrangements.</p><img class="hero" src="kept-trace.png" alt="Recorded movement remains as pink segments in the playable scene"><p class="caption">A record of movement is a persistent object here. Each new grab begins a separate stroke.</p></section>
<section id="lineage"><h2>What returns from the tutorials?</h2><p><strong>PointBody</strong> supplies the sphere and XR pickup. <strong>BoxBody</strong> supplies the block and architectural parts. <strong>LineSkin</strong> supplies the stick and recorded segments. The game adds explicit collision, placement, action, completion and storage.</p><p>The biome is supplied scenery. This episode does not yet import the student's earlier saved trace, teach the whole biome, or replace the canonical lessons. It begins a continuing place where later lessons can leave consequences.</p><p>The next useful addition is a cube that can leave copies: the same source becomes a walkway or frame the player chooses.</p></section>
<section id="evidence"><h2>Evidence</h2><p>__NATIVE__ native checks passed. __MENU__ menu-route checks passed. <a href="checks.json">Gameplay results</a> · <a href="menu-checks.json">Menu results</a> · <a href="receipt.json">Source receipt</a></p><p class="small">Synthetic XR/desktop input, a real physics traversal and independent state reconstruction. Physical headset comfort and human learning have not been tested. Process-exit status and known staging limitations are recorded in <a href="REPORT.md">the report</a>.</p><ul class="links">__LINKS__</ul></section></main></html>'''
page = page.replace('__NATIVE__',f"{native_count}/{len(native['checks'])}").replace('__MENU__',f"{menu_count}/{len(menu['checks'])}").replace('__LINKS__',links)
page = page.replace('/book-review/commons/shadow_game/shadow_game.tscn', 'sources/commons/shadow_game/shadow_game.tscn.txt')
page = page.replace('<section id="evidence"><h2>Evidence</h2>', '<section id="evidence"><h2>Evidence</h2><aside><strong>Export dependency repair</strong><br>The crossing now uses the shared runtime form builders. Eight packaged Shadow Game checks pass with documentation absent: construction, pickup bodies, buttons, point inheritance, cube placement, bridge action, trace and completion. <a href="../2026-10-17-museum-runner/package-receipt.json">Combined package evidence</a>.<br><span class="small">The full world passes the native checks below. An installed Quest build needs a new export; physical headset play remains unverified.</span></aside>')
page = page.replace('Process-exit status and known staging limitations are recorded in', 'The native run exited cleanly. The menu test still encounters a staging shutdown crash; details are recorded in')
(HERE / "index.html").write_text(page,encoding="utf-8")
print(HERE / "index.html")
